WITH cases(course_slug,lesson_no,redteam) AS (VALUES
('bednarz',16,'{"question":"Po szczelnym teście wodą klient chce wpisać w karcie «bezpieczna do soku». Co jest wadą tego wniosku?","options":["Wystarczy przedłużyć test szczelności o dobę i dopisać wyniki.","Wystarczy wyparzyć beczkę i odnotować brak zapachu.","Zapis «na własną odpowiedzialność» zastępuje kontrolę materiałów.","Brak potwierdzenia materiałów, powłok i historii użycia; wynik szczelności opisuje tylko szczelność."],"correct":3,"feedback":["To pomija ważne kryterium. Pomieszanie szczelności konstrukcyjnej z higieną produktu.","To pomija ważne kryterium. Pomieszanie szczelności konstrukcyjnej z higieną produktu.","To pomija ważne kryterium. Pomieszanie szczelności konstrukcyjnej z higieną produktu.","Prawidłowo. Brak potwierdzenia materiałów, powłok i historii użycia; wynik szczelności opisuje tylko szczelność."],"root_cause":"Pomieszanie szczelności konstrukcyjnej z higieną produktu.","evidence":"Identyfikacja materiałów, powłok, wcześniejszego zastosowania i dokumentów kontaktu z żywnością.","severity":"critical","reviewer_profile":"Technolog drewna i wilgotności","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('bednarz',17,'{"question":"Do 25 gotowych klepek przy 80% uzysku kupiec zamawia 31 sztuk. Jak audytor oceni rachunek?","options":["31 jest wystarczające, bo końcówkę 0,25 się pomija.","30 wystarcza, ponieważ 20% z 25 to pięć odpadów.","31 sztuk nie wystarczy według tego założenia: 25/0,80 = 31,25, więc planuj co najmniej 32 półfabrykaty.","32 gwarantuje wynik bez ryzyka, więc nie trzeba rejestrować strat."],"correct":2,"feedback":["To pomija ważne kryterium. Niewłaściwe zaokrąglenie liczby sztuk lub traktowanie oczekiwanego uzysku jako gwarancji.","To pomija ważne kryterium. Niewłaściwe zaokrąglenie liczby sztuk lub traktowanie oczekiwanego uzysku jako gwarancji.","Prawidłowo. 31 sztuk nie wystarczy według tego założenia: 25/0,80 = 31,25, więc planuj co najmniej 32 półfabrykaty.","To pomija ważne kryterium. Niewłaściwe zaokrąglenie liczby sztuk lub traktowanie oczekiwanego uzysku jako gwarancji."],"root_cause":"Niewłaściwe zaokrąglenie liczby sztuk lub traktowanie oczekiwanego uzysku jako gwarancji.","evidence":"Wzór 25/0,8, zaokrąglenie w górę i osobny bilans rzeczywistych odrzutów.","severity":"high","reviewer_profile":"Specjalista planowania rozkroju i wydajności","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('bednarz',18,'{"question":"Beczka po renowacji jest szczelna, ale nieznany jest lakier wnętrza. Jak sformułować ofertę?","options":["Oznaczyć jako spożywczą po samym wietrzeniu i płukaniu.","Nie deklarować przydatności do napojów; ograniczyć przeznaczenie do potwierdzonego i żądać dokumentacji materiałowej.","Załączyć zdjęcia wnętrza, a kwestię powłoki pominąć.","Umieścić w opisie «naturalne drewno», uznając to za dowód."],"correct":1,"feedback":["To pomija ważne kryterium. Brak identyfikowalności materiału i nieuprawniona deklaracja żywnościowa.","Prawidłowo. Nie deklarować przydatności do napojów; ograniczyć przeznaczenie do potwierdzonego i żądać dokumentacji materiałowej.","To pomija ważne kryterium. Brak identyfikowalności materiału i nieuprawniona deklaracja żywnościowa.","To pomija ważne kryterium. Brak identyfikowalności materiału i nieuprawniona deklaracja żywnościowa."],"root_cause":"Brak identyfikowalności materiału i nieuprawniona deklaracja żywnościowa.","evidence":"Dane lakieru i materiału, identyfikowalność oraz wymagania właściwe dla deklarowanego kontaktu z żywnością.","severity":"critical","reviewer_profile":"Audytor bezpieczeństwa materiałów do kontaktu z żywnością","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://www.gov.pl/web/gis/materialy-i-wyroby-przeznaczone-do-konaktu-z-zywnoscia","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('bednarz',19,'{"question":"Protokół beczki zawiera 10 pomiarów, lecz puste pole «przeznaczenie». Czy to pełny odbiór?","options":["Nie: bez przeznaczenia nie wiadomo, które kryteria bezpieczeństwa i użytkowania należało sprawdzić.","Tak, bo liczba wykonanych pomiarów sama potwierdza funkcję.","Tak, jeśli klient pisemnie zaakceptuje wygląd wyrobu.","Tak, jeśli dopisze się uniwersalny limit obciążenia."],"correct":0,"feedback":["Prawidłowo. Nie: bez przeznaczenia nie wiadomo, które kryteria bezpieczeństwa i użytkowania należało sprawdzić.","To pomija ważne kryterium. Protokół bez funkcji wyrobu może sugerować nieprzeprowadzoną kontrolę.","To pomija ważne kryterium. Protokół bez funkcji wyrobu może sugerować nieprzeprowadzoną kontrolę.","To pomija ważne kryterium. Protokół bez funkcji wyrobu może sugerować nieprzeprowadzoną kontrolę."],"root_cause":"Protokół bez funkcji wyrobu może sugerować nieprzeprowadzoną kontrolę.","evidence":"Opis zastosowania, rodzaj materiału, wymagane pomiary, ograniczenia i identyfikacja osoby odbierającej.","severity":"high","reviewer_profile":"Kontroler jakości wyrobu bednarskiego","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',8,'{"question":"Na palecie detale B, na serwerze rewizja C oznaczona «do koordynacji». Czy można już montować według C?","options":["Tak, bo każda litera C jest z definicji wydaniem do montażu.","Można montować B, jeśli ilość sztuk odpowiada zamówieniu.","Można łączyć B i C, jeśli wymiary na pierwszy rzut oka pasują.","Nie; trzeba ustalić wydaną do realizacji rewizję, zakres zmian i zgodność dostawy przed montażem."],"correct":3,"feedback":["To pomija ważne kryterium. Data lub litera rewizji bez statusu dokumentu nie oznacza zatwierdzenia.","To pomija ważne kryterium. Data lub litera rewizji bez statusu dokumentu nie oznacza zatwierdzenia.","To pomija ważne kryterium. Data lub litera rewizji bez statusu dokumentu nie oznacza zatwierdzenia.","Prawidłowo. Nie; trzeba ustalić wydaną do realizacji rewizję, zakres zmian i zgodność dostawy przed montażem."],"root_cause":"Data lub litera rewizji bez statusu dokumentu nie oznacza zatwierdzenia.","evidence":"Rejestr wydań, numer detalu, status dokumentu i pisemne wyjaśnienie różnic.","severity":"critical","reviewer_profile":"Koordynator dokumentacji technicznej BIM i rewizji","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',9,'{"question":"Laser na +700 mm względem zera. Punkt jest 250 mm poniżej wiązki. Jaka rzędna punktu?","options":["+950 mm, ponieważ offset trzeba doliczyć do odczytu.","−450 mm, ponieważ odległość od lasera zawsze jest ujemna.","+450 mm względem tego samego zera, ponieważ +700 mm − 250 mm = +450 mm.","+450 mm i jeszcze −700 mm podczas wpisywania protokołu."],"correct":2,"feedback":["To pomija ważne kryterium. Podwójne uwzględnienie offsetu lub pomieszanie osi i znaków.","To pomija ważne kryterium. Podwójne uwzględnienie offsetu lub pomieszanie osi i znaków.","Prawidłowo. +450 mm względem tego samego zera, ponieważ +700 mm − 250 mm = +450 mm.","To pomija ważne kryterium. Podwójne uwzględnienie offsetu lub pomieszanie osi i znaków."],"root_cause":"Podwójne uwzględnienie offsetu lub pomieszanie osi i znaków.","evidence":"Szkic zera, położenie lasera, kierunek odczytu i sprawdzenie znaku wyniku.","severity":"high","reviewer_profile":"Geodeta budowlany i specjalista punktów odniesienia","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',10,'{"question":"Wynik elementu to +8 mm, lecz tolerancji w zatwierdzonej dokumentacji brak. Jak brzmieć powinien status?","options":["«Zgodny, bo +8 mm w budowlance jest typowe».","«Wynik +8 mm; zgodność nieustalona — wymagana specyfikacja i decyzja uprawnionej osoby».","«Niezgodny, do poprawy o 8 mm», bez sprawdzenia połączenia.","«Zgodny pod warunkiem, że przyjmiemy ±10 mm»."],"correct":1,"feedback":["To pomija ważne kryterium. Zamiana pomiaru w ocenę zgodności bez kryterium.","Prawidłowo. «Wynik +8 mm; zgodność nieustalona — wymagana specyfikacja i decyzja uprawnionej osoby».","To pomija ważne kryterium. Zamiana pomiaru w ocenę zgodności bez kryterium.","To pomija ważne kryterium. Zamiana pomiaru w ocenę zgodności bez kryterium."],"root_cause":"Zamiana pomiaru w ocenę zgodności bez kryterium.","evidence":"Źródło tolerancji, stan montażu, zapis pomiaru i decyzja zatwierdzająca.","severity":"critical","reviewer_profile":"Inżynier jakości i tolerancji montażowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',11,'{"question":"Zmiana frontu na klatkę B pozwoli dotrzymać terminu, ale instalatorzy są tam w tym samym czasie. Które rozwiązanie jest wykonalne?","options":["Uzgodnienie czasu i granic strefy między ekipami wraz z aktualizacją oceny ryzyka oraz harmonogramu.","Wysłanie obu ekip z poleceniem wzajemnego ustępowania.","Przeniesienie tylko terminu w ERP bez odprawy na budowie.","Oznaczenie miejsca jako wolnego, jeżeli nie ma tam materiału."],"correct":0,"feedback":["Prawidłowo. Uzgodnienie czasu i granic strefy między ekipami wraz z aktualizacją oceny ryzyka oraz harmonogramu.","To pomija ważne kryterium. Pomylenie dostępności harmonogramowej z faktycznym bezpiecznym dostępem.","To pomija ważne kryterium. Pomylenie dostępności harmonogramowej z faktycznym bezpiecznym dostępem.","To pomija ważne kryterium. Pomylenie dostępności harmonogramowej z faktycznym bezpiecznym dostępem."],"root_cause":"Pomylenie dostępności harmonogramowej z faktycznym bezpiecznym dostępem.","evidence":"Odprawa obu ekip, uzgodnione okno, osoba odpowiedzialna i zapis przekazania.","severity":"high","reviewer_profile":"Planista kolejności robót i konfliktów międzybranżowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',12,'{"question":"Dźwig ma podnieść jedną z 4 palet o łącznej masie 4,8 t. Czego brak do doboru urządzenia?","options":["Średniej masy 1,2 t przy zachowaniu tej samej liczby palet.","Samej nominalnej masy całej ciężarówki i czasu rozładunku.","Tylko potwierdzenia, że kierowca ma uprawnienia kategorii C.","Mas najcięższej palety, promienia podnoszenia, sposobu zawieszenia, danych sprzętu i podłoża."],"correct":3,"feedback":["To pomija ważne kryterium. Użycie średniej masy zamiast danych obciążenia konkretnego podnoszenia.","To pomija ważne kryterium. Użycie średniej masy zamiast danych obciążenia konkretnego podnoszenia.","To pomija ważne kryterium. Użycie średniej masy zamiast danych obciążenia konkretnego podnoszenia.","Prawidłowo. Mas najcięższej palety, promienia podnoszenia, sposobu zawieszenia, danych sprzętu i podłoża."],"root_cause":"Użycie średniej masy zamiast danych obciążenia konkretnego podnoszenia.","evidence":"Masy jednostkowe, DOR zawiesi, diagram udźwigu przy promieniu i zabezpieczenie strefy.","severity":"critical","reviewer_profile":"Kierownik operacji dźwigowych i zawiesi","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',13,'{"question":"Brak dostępu do podestu, za to jest drabina. Tafla ciężka, dwóch monterów i jedno piętro. Co robi kierujący?","options":["Dopuszcza drabinę, jeśli obaj monterzy mają kaski.","Dopuszcza wariant, jeżeli klient zgodzi się ustnie.","Wstrzymuje ten sposób transportu i organizuje bezpieczną metodę dostępu oraz przeniesienia tafli.","Wybiera drabinę, jeśli cała czynność potrwa mniej niż pięć minut."],"correct":2,"feedback":["To pomija ważne kryterium. Zastąpienie oceny ryzyka kryterium czasu, kasku lub liczby osób.","To pomija ważne kryterium. Zastąpienie oceny ryzyka kryterium czasu, kasku lub liczby osób.","Prawidłowo. Wstrzymuje ten sposób transportu i organizuje bezpieczną metodę dostępu oraz przeniesienia tafli.","To pomija ważne kryterium. Zastąpienie oceny ryzyka kryterium czasu, kasku lub liczby osób."],"root_cause":"Zastąpienie oceny ryzyka kryterium czasu, kasku lub liczby osób.","evidence":"Instrukcja sprzętu, analiza transportu szkła, ryzyko upadku i przeszkolenie operatorów.","severity":"critical","reviewer_profile":"Specjalista bezpieczeństwa pracy na wysokości","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://www.arbeidstilsynet.no/risikofylt-arbeid/arbeid-i-hoyden/","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',14,'{"question":"Rysa na opakowaniu i wyszczerbiona krawędź tafli trafiają do jednego protokołu. Czy można oznaczyć oba jako «uszkodzenie opakowania»?","options":["Tak, jeśli w profilu po montażu nie będzie widoczne.","Nie; uszkodzenie tafli wymaga osobnego oznaczenia, zabezpieczenia i decyzji jakościowej przed montażem.","Tak, jeśli monter sfotografuje tylko całą paletę.","Tak, jeśli dostawca obieca wymianę po odbiorze."],"correct":1,"feedback":["To pomija ważne kryterium. Ukrywanie wady szkła w ogólnej etykiecie dostawy.","Prawidłowo. Nie; uszkodzenie tafli wymaga osobnego oznaczenia, zabezpieczenia i decyzji jakościowej przed montażem.","To pomija ważne kryterium. Ukrywanie wady szkła w ogólnej etykiecie dostawy.","To pomija ważne kryterium. Ukrywanie wady szkła w ogólnej etykiecie dostawy."],"root_cause":"Ukrywanie wady szkła w ogólnej etykiecie dostawy.","evidence":"Zdjęcie i identyfikacja tafli, ocena krawędzi oraz decyzja co do przyjęcia.","severity":"critical","reviewer_profile":"Inspektor jakości szkła architektonicznego","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',15,'{"question":"4 pracowników × 7 h obecności, w tym wspólne 1 h czekania. Jak rozdzielić ewidencję?","options":["28 rbh obecności = 24 rbh aktywnej pracy i 4 rbh czekania; ewentualne rozliczenie przestoju to osobna sprawa.","24 rbh obecności i 4 rbh czasu kalendarzowego.","28 rbh aktywnej pracy, bo ekipa była na miejscu.","27 rbh pracy, bo godzinę czekania odejmuje się raz od całej ekipy."],"correct":0,"feedback":["Prawidłowo. 28 rbh obecności = 24 rbh aktywnej pracy i 4 rbh czekania; ewentualne rozliczenie przestoju to osobna sprawa.","To pomija ważne kryterium. Mylenie czasu kalendarzowego i sumy godzin wszystkich pracowników.","To pomija ważne kryterium. Mylenie czasu kalendarzowego i sumy godzin wszystkich pracowników.","To pomija ważne kryterium. Mylenie czasu kalendarzowego i sumy godzin wszystkich pracowników."],"root_cause":"Mylenie czasu kalendarzowego i sumy godzin wszystkich pracowników.","evidence":"Liczba osób, godziny faktyczne, rozdział pracy/przestoju i zasada ewidencji.","severity":"high","reviewer_profile":"Specjalista planowania roboczogodzin","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',16,'{"question":"Przestój 5 rbh × 550 NOK/rbh dał 2750 NOK. Czy w ERP można oznaczyć kwotę jako zaakceptowaną zmianę?","options":["Tak, bo iloczyn jest matematycznie poprawny.","Tak, jeśli opis przestoju znalazł się w raporcie wewnętrznym.","Tak, jeśli klient był na budowie w chwili zdarzenia.","Nie: to koszt według przyjętej stawki, który wymaga analizy kontraktu, dowodów i akceptacji rozliczenia."],"correct":3,"feedback":["To pomija ważne kryterium. Przekształcenie kalkulacyjnego kosztu w automatyczne roszczenie.","To pomija ważne kryterium. Przekształcenie kalkulacyjnego kosztu w automatyczne roszczenie.","To pomija ważne kryterium. Przekształcenie kalkulacyjnego kosztu w automatyczne roszczenie.","Prawidłowo. Nie: to koszt według przyjętej stawki, który wymaga analizy kontraktu, dowodów i akceptacji rozliczenia."],"root_cause":"Przekształcenie kalkulacyjnego kosztu w automatyczne roszczenie.","evidence":"Dokumenty przestoju, warunki kontraktu, tryb zgłoszenia i potwierdzona decyzja.","severity":"critical","reviewer_profile":"Kontroler kosztów robót i zmian kontraktowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',17,'{"question":"Klient zgłosił dwa wsporniki telefonicznie. Czy dokument z kosztorysem sam zatwierdza zmianę?","options":["Tak, jeśli kopia kosztorysu trafiła do wszystkich monterów.","Tak, jeśli nie otrzymano sprzeciwu w dniu wysłania.","Nie; należy zastosować tryb uzgodnienia i potwierdzenia przewidziany w danym kontrakcie.","Tak, jeśli klient miał możliwość obejrzenia detalu na budowie."],"correct":2,"feedback":["To pomija ważne kryterium. Brak rozdzielenia zgłoszenia i zaakceptowanej zmiany kontraktowej.","To pomija ważne kryterium. Brak rozdzielenia zgłoszenia i zaakceptowanej zmiany kontraktowej.","Prawidłowo. Nie; należy zastosować tryb uzgodnienia i potwierdzenia przewidziany w danym kontrakcie.","To pomija ważne kryterium. Brak rozdzielenia zgłoszenia i zaakceptowanej zmiany kontraktowej."],"root_cause":"Brak rozdzielenia zgłoszenia i zaakceptowanej zmiany kontraktowej.","evidence":"Źródło zmiany, wycena, wpływ na termin, wymagany tryb akceptacji i ślad decyzji.","severity":"critical","reviewer_profile":"Specjalista kontraktów budowlanych i zmian VO","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',18,'{"question":"Wykonano 36/40 m, odebrano 28/40 m. Ile metrów zostało wykonanych, ale nieodebranych?","options":["12 m, bo tyle pozostało do pełnego odbioru.","8 m, przy 90% montażu i 70% odbioru; te statusy należy raportować oddzielnie.","4 m, bo tyle nie ukończono w montażu.","16 m, bo różnica procentowa wynosi 20 punktów."],"correct":1,"feedback":["To pomija ważne kryterium. Pomieszanie części niezamontowanej z zamontowaną, lecz nieodebraną.","Prawidłowo. 8 m, przy 90% montażu i 70% odbioru; te statusy należy raportować oddzielnie.","To pomija ważne kryterium. Pomieszanie części niezamontowanej z zamontowaną, lecz nieodebraną.","To pomija ważne kryterium. Pomieszanie części niezamontowanej z zamontowaną, lecz nieodebraną."],"root_cause":"Pomieszanie części niezamontowanej z zamontowaną, lecz nieodebraną.","evidence":"Trzy liczniki: planowane, wykonane, odebrane, ze stanem i datą.","severity":"high","reviewer_profile":"Inżynier raportowania zaawansowania robót","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('brygadzista',19,'{"question":"Brak zatwierdzonego detalu mocowania, a podwykonawca ma bezpieczne zadanie niezależne. Co jest racjonalne?","options":["Wstrzymać sporne mocowanie, kontynuować wyłącznie niezależne i bezpieczne prace po koordynacji.","Rozpocząć wszystkie mocowania na starszym detalu i później poprawić.","Wstrzymać cały projekt do czasu potwierdzenia każdego dokumentu.","Przenieść sporny montaż na inną strefę bez zmiany dokumentacji."],"correct":0,"feedback":["Prawidłowo. Wstrzymać sporne mocowanie, kontynuować wyłącznie niezależne i bezpieczne prace po koordynacji.","To pomija ważne kryterium. Fałszywy wybór między niebezpiecznym montażem a całkowitą bezczynnością.","To pomija ważne kryterium. Fałszywy wybór między niebezpiecznym montażem a całkowitą bezczynnością.","To pomija ważne kryterium. Fałszywy wybór między niebezpiecznym montażem a całkowitą bezczynnością."],"root_cause":"Fałszywy wybór między niebezpiecznym montażem a całkowitą bezczynnością.","evidence":"Lista zależności, dopuszczonych zadań, zablokowanych prac i osób decyzyjnych.","severity":"high","reviewer_profile":"Kierownik budowy — zarządzanie ryzykiem harmonogramu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',12,'{"question":"VIN z nadwozia i ogłoszenia zgodny, wersja silnika w dokumencie różna. Który wniosek jest uprawniony?","options":["Pojazd należy uznać za kradziony bez dalszych ustaleń.","Jeśli raport VIN się zgadza, dokument silnika nie ma znaczenia.","Wystarczy zapewnienie sprzedawcy o wymianie silnika, bez dowodu.","To rozbieżność do wyjaśnienia przed transakcją; sama w sobie nie dowodzi oszustwa ani nie znika po raporcie online."],"correct":3,"feedback":["To pomija ważne kryterium. Przypisywanie przyczyny rozbieżności bez dokumentów.","To pomija ważne kryterium. Przypisywanie przyczyny rozbieżności bez dokumentów.","To pomija ważne kryterium. Przypisywanie przyczyny rozbieżności bez dokumentów.","Prawidłowo. To rozbieżność do wyjaśnienia przed transakcją; sama w sobie nie dowodzi oszustwa ani nie znika po raporcie online."],"root_cause":"Przypisywanie przyczyny rozbieżności bez dokumentów.","evidence":"VIN na pojeździe, dokument rejestracyjny, konfiguracja i dokumenty zmian.","severity":"high","reviewer_profile":"Rzeczoznawca identyfikacji pojazdów i VIN","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',13,'{"question":"Dwa lata temu zapisano 172 tys. km, teraz 163 tys. km. Sprzedający mówi o błędzie wpisu. Co wystarczy?","options":["Wystarczy oświadczenie sprzedawcy i aktualna diagnostyka.","Wystarczy ocena zużycia kierownicy w czasie oględzin.","Nie samo wyjaśnienie: należy porównać kolejne wpisy i dokumenty oraz ustalić przyczynę rozbieżności.","Wystarczy przyjęcie większej wartości bez dalszych dowodów."],"correct":2,"feedback":["To pomija ważne kryterium. Zastąpienie weryfikacji przebiegu jedną poszlaką lub oświadczeniem.","To pomija ważne kryterium. Zastąpienie weryfikacji przebiegu jedną poszlaką lub oświadczeniem.","Prawidłowo. Nie samo wyjaśnienie: należy porównać kolejne wpisy i dokumenty oraz ustalić przyczynę rozbieżności.","To pomija ważne kryterium. Zastąpienie weryfikacji przebiegu jedną poszlaką lub oświadczeniem."],"root_cause":"Zastąpienie weryfikacji przebiegu jedną poszlaką lub oświadczeniem.","evidence":"Chronologia zapisów, faktury serwisowe, odczyty i wiarygodne wyjaśnienie.","severity":"high","reviewer_profile":"Diagnosta historii przebiegu pojazdu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',14,'{"question":"EV pokazuje 400 km zasięgu na 100%. Czy z tego wynika SoH akumulatora?","options":["Tak, jeśli zasięg zmierzono w ciepły dzień przy pełnym naładowaniu.","Nie; zasięg jest estymacją zależną od warunków, a do oceny baterii potrzeba metody właściwej dla modelu.","Tak, jeśli samochód przejechał tylko krótki odcinek próbny.","Tak, jeśli nie świeci się kontrolka awarii baterii."],"correct":1,"feedback":["To pomija ważne kryterium. Przypisywanie wskaźnikowi zasięgu statusu profesjonalnego testu pojemności.","Prawidłowo. Nie; zasięg jest estymacją zależną od warunków, a do oceny baterii potrzeba metody właściwej dla modelu.","To pomija ważne kryterium. Przypisywanie wskaźnikowi zasięgu statusu profesjonalnego testu pojemności.","To pomija ważne kryterium. Przypisywanie wskaźnikowi zasięgu statusu profesjonalnego testu pojemności."],"root_cause":"Przypisywanie wskaźnikowi zasięgu statusu profesjonalnego testu pojemności.","evidence":"Opis metody testu SoH, warunki i zakres pomiaru oraz raport błędów.","severity":"high","reviewer_profile":"Technik diagnostyki akumulatorów trakcyjnych EV","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',15,'{"question":"Auto 28 000 zł, rozpoznane naprawy 3000 zł. Kwota 31 000 zł oznacza co dokładnie?","options":["Minimalny budżet ceny i wskazanych napraw, ale bez pozostałych formalności i nierozpoznanych usterek.","Pełny koszt posiadania przez pierwszy rok.","Gwarancję, że żadne inne naprawy nie będą konieczne.","Kwotę wystarczającą również na wszystkie formalności i ubezpieczenie."],"correct":0,"feedback":["Prawidłowo. Minimalny budżet ceny i wskazanych napraw, ale bez pozostałych formalności i nierozpoznanych usterek.","To pomija ważne kryterium. Przedstawienie budżetu cząstkowego jako całkowitego kosztu samochodu.","To pomija ważne kryterium. Przedstawienie budżetu cząstkowego jako całkowitego kosztu samochodu.","To pomija ważne kryterium. Przedstawienie budżetu cząstkowego jako całkowitego kosztu samochodu."],"root_cause":"Przedstawienie budżetu cząstkowego jako całkowitego kosztu samochodu.","evidence":"Pozycje napraw w kosztorysie, dane warsztatu i rezerwa na nieznane koszty.","severity":"medium","reviewer_profile":"Mechanik przeglądów przedzakupowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',16,'{"question":"Dwie oferty mają identyczną ratę, ale różnią się okresem i wykupem. Jak ocenić koszt?","options":["Wybrać krótszy okres bez weryfikowania prowizji.","Wybrać większą wpłatę własną niezależnie od jej wpływu na koszt.","Porównać tylko nominalne oprocentowanie i ratę.","Zsumować raty i pozostałe opłaty, porównać RRSO na zgodnych założeniach oraz obowiązki umowne."],"correct":3,"feedback":["To pomija ważne kryterium. Pomijanie wykupu końcowego i kosztów dodatkowych.","To pomija ważne kryterium. Pomijanie wykupu końcowego i kosztów dodatkowych.","To pomija ważne kryterium. Pomijanie wykupu końcowego i kosztów dodatkowych.","Prawidłowo. Zsumować raty i pozostałe opłaty, porównać RRSO na zgodnych założeniach oraz obowiązki umowne."],"root_cause":"Pomijanie wykupu końcowego i kosztów dodatkowych.","evidence":"Harmonogram, wykup, prowizje, ubezpieczenia wymagane i kwota do zapłaty.","severity":"high","reviewer_profile":"Analityk kredytu konsumenckiego na zakup auta","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',17,'{"question":"Komis wystawia ogłoszenie, umowę podpisuje osoba fizyczna. Czy prawa konsumenta z definicji dotyczą sprzedającego komis?","options":["Tak, ponieważ auto stało na placu komisu.","Tak, jeśli komis przygotował formularz umowy.","Nie: najpierw należy ustalić faktycznego sprzedawcę i charakter transakcji, w tym rolę komisu.","Nie, ponieważ sam tytuł umowy przesądza pełną sytuację prawną."],"correct":2,"feedback":["To pomija ważne kryterium. Automatyczne zastosowanie lub wyłączenie ochrony konsumenckiej bez ustalenia strony umowy.","To pomija ważne kryterium. Automatyczne zastosowanie lub wyłączenie ochrony konsumenckiej bez ustalenia strony umowy.","Prawidłowo. Nie: najpierw należy ustalić faktycznego sprzedawcę i charakter transakcji, w tym rolę komisu.","To pomija ważne kryterium. Automatyczne zastosowanie lub wyłączenie ochrony konsumenckiej bez ustalenia strony umowy."],"root_cause":"Automatyczne zastosowanie lub wyłączenie ochrony konsumenckiej bez ustalenia strony umowy.","evidence":"Dane sprzedawcy, pełnomocnictwo/pośrednictwo, umowa i dowody transakcji.","severity":"critical","reviewer_profile":"Prawnik ochrony konsumentów i transakcji samochodowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://prawakonsumenta.uokik.gov.pl/pytania-i-odpowiedzi/zagadnienia-ogolne/","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',18,'{"question":"Przy zakupie zwykłego auta w Polsce, termin na wniosek o rejestrację to 30 dni. A w razie spadku?","options":["Zawsze 30 dni od śmierci spadkodawcy.","Co do zasady 60 dni, liczone od prawomocnego orzeczenia albo sporządzenia aktu poświadczenia dziedziczenia.","Zawsze 60 dni od daty zakupu samochodu.","90 dni od podpisania umowy, nawet gdy nie jest się przedsiębiorcą handlującym autami."],"correct":1,"feedback":["To pomija ważne kryterium. Zastosowanie jednego terminu do różnych podstaw nabycia.","Prawidłowo. Co do zasady 60 dni, liczone od prawomocnego orzeczenia albo sporządzenia aktu poświadczenia dziedziczenia.","To pomija ważne kryterium. Zastosowanie jednego terminu do różnych podstaw nabycia.","To pomija ważne kryterium. Zastosowanie jednego terminu do różnych podstaw nabycia."],"root_cause":"Zastosowanie jednego terminu do różnych podstaw nabycia.","evidence":"Data zdarzenia prawnego, rodzaj nabycia i źródło gov.pl aktualne na dzień kursu.","severity":"critical","reviewer_profile":"Specjalista formalności rejestracyjnych w Polsce","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://www.gov.pl/web/infrastruktura/rejestracja-pojazdow","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('jak-kupic-samochod',19,'{"question":"Auto 35 tys., serwis 1800 zł, rezerwa 1200 zł. Co opisuje wynik 38 tys. zł?","options":["Budżet początkowy tych trzech pozycji, przed podatkiem, ubezpieczeniem i innymi nieznanymi kosztami.","Pełny koszt 90 dni niezależnie od dalszego użytkowania.","Samą wartość pojazdu po wykonaniu napraw.","Wartość auta podlegającą automatycznie odzyskaniu przy odsprzedaży."],"correct":0,"feedback":["Prawidłowo. Budżet początkowy tych trzech pozycji, przed podatkiem, ubezpieczeniem i innymi nieznanymi kosztami.","To pomija ważne kryterium. Fałszywa precyzja kosztorysu przy nieznanych kosztach i warunkach.","To pomija ważne kryterium. Fałszywa precyzja kosztorysu przy nieznanych kosztach i warunkach.","To pomija ważne kryterium. Fałszywa precyzja kosztorysu przy nieznanych kosztach i warunkach."],"root_cause":"Fałszywa precyzja kosztorysu przy nieznanych kosztach i warunkach.","evidence":"Pisemna wycena serwisu, rezerwa, koszty formalności i termin ponownej oceny.","severity":"medium","reviewer_profile":"Doradca planowania obsługi serwisowej pojazdu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('kolodziej',16,'{"question":"Bicie promieniowe ma różnicę odczytu 5 mm, bez specyfikacji. Czy dopuszczasz koło do jazdy?","options":["Tak, po zaokrągleniu odchylenia do pełnego centymetra.","Tak, jeśli bicie boczne wygląda na mniejsze.","Tak, jeżeli odczyty wykonano tą samą miarką.","Nie; zapisujesz wynik i żądasz kryterium odpowiedniego do przeznaczenia przed decyzją o użytkowaniu."],"correct":3,"feedback":["To pomija ważne kryterium. Nieuzgodniony limit geometrii koła użytkowego.","To pomija ważne kryterium. Nieuzgodniony limit geometrii koła użytkowego.","To pomija ważne kryterium. Nieuzgodniony limit geometrii koła użytkowego.","Prawidłowo. Nie; zapisujesz wynik i żądasz kryterium odpowiedniego do przeznaczenia przed decyzją o użytkowaniu."],"root_cause":"Nieuzgodniony limit geometrii koła użytkowego.","evidence":"Oś odniesienia, sposób pomiaru, przeznaczenie, tolerancja i ocena konstrukcyjna.","severity":"critical","reviewer_profile":"Metrolog kół i bicia obręczy","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('kolodziej',17,'{"question":"Naprawiono jedną luźną szprychę, ale nie obejrzano gniazda piasty. Czy odbiór jest możliwy?","options":["Tak, jeżeli koło obraca się bez widocznego bicia.","Tak, jeśli nowa szprycha jest z twardego drewna.","Nie; gniazdo, sąsiednie połączenia i geometria wymagają sprawdzenia przed decyzją.","Tak, jeśli nie ma na zewnątrz widocznych pęknięć."],"correct":2,"feedback":["To pomija ważne kryterium. Ocena jednego połączenia zamiast układu przenoszącego obciążenia.","To pomija ważne kryterium. Ocena jednego połączenia zamiast układu przenoszącego obciążenia.","Prawidłowo. Nie; gniazdo, sąsiednie połączenia i geometria wymagają sprawdzenia przed decyzją.","To pomija ważne kryterium. Ocena jednego połączenia zamiast układu przenoszącego obciążenia."],"root_cause":"Ocena jednego połączenia zamiast układu przenoszącego obciążenia.","evidence":"Piasta, gniazda, szprychy, włókna i pomiary całej geometrii.","severity":"critical","reviewer_profile":"Rzemieślnik konstrukcji piasty i szprych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('kolodziej',18,'{"question":"Konserwator zachowuje starą naprawę w kole muzealnym. Klient chce na nim jeździć. Co dalej?","options":["Próba jazdy bez obciążenia jest wystarczającą kontrolą.","To zmiana przeznaczenia, której odbiór eksponatu nie obejmuje; potrzeba osobnej oceny i prób.","Wiek drewna sam potwierdza tradycyjną wytrzymałość.","Wystarczy lakierować obręcz, aby naprawa nie przeszkadzała."],"correct":1,"feedback":["To pomija ważne kryterium. Traktowanie dokumentacji konserwatorskiej jako certyfikatu eksploatacyjnego.","Prawidłowo. To zmiana przeznaczenia, której odbiór eksponatu nie obejmuje; potrzeba osobnej oceny i prób.","To pomija ważne kryterium. Traktowanie dokumentacji konserwatorskiej jako certyfikatu eksploatacyjnego.","To pomija ważne kryterium. Traktowanie dokumentacji konserwatorskiej jako certyfikatu eksploatacyjnego."],"root_cause":"Traktowanie dokumentacji konserwatorskiej jako certyfikatu eksploatacyjnego.","evidence":"Karta eksponatu, zakres prac, warunki przechowania i odrębna kwalifikacja do jazdy.","severity":"critical","reviewer_profile":"Konserwator historycznych pojazdów i eksponatów","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('kolodziej',19,'{"question":"Karta koła nie podaje obciążeń ani przeznaczenia. Czy podpis klienta zamyka ryzyko?","options":["Nie; podpis odbioru nie zastępuje potrzebnej dokumentacji funkcji i kontroli konstrukcyjnej.","Tak, podpis klienta przenosi każde ryzyko na kupującego.","Tak, jeśli drewno posiada fakturę zakupu.","Tak, jeśli koło jest oznaczone jako ręcznie wykonane."],"correct":0,"feedback":["Prawidłowo. Nie; podpis odbioru nie zastępuje potrzebnej dokumentacji funkcji i kontroli konstrukcyjnej.","To pomija ważne kryterium. Przerzucanie odpowiedzialności na klienta zamiast rzetelnej dokumentacji.","To pomija ważne kryterium. Przerzucanie odpowiedzialności na klienta zamiast rzetelnej dokumentacji.","To pomija ważne kryterium. Przerzucanie odpowiedzialności na klienta zamiast rzetelnej dokumentacji."],"root_cause":"Przerzucanie odpowiedzialności na klienta zamiast rzetelnej dokumentacji.","evidence":"Rysunek, geometra, materiały, ograniczenia i przeznaczenie, komplet pomiarów.","severity":"critical","reviewer_profile":"Audytor jakości zleceń kołodziejskich","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',8,'{"question":"Masz 20 minut i dziecko chce pokazać budowlę, choć umówiłeś spacer. Co świadczy o uważnym kontakcie?","options":["Przełożenie rozmowy na wieczór bez sprawdzania, czy dziecko ma wtedy czas.","Pokazanie dziecku planu spaceru i ustalenie kolejnego terminu na budowlę bez pytania o jego zdanie.","Wspólne zdjęcie budowli i późniejsze oglądanie go przy odpowiadaniu na wiadomości.","Zapytanie, na czym mu zależy, uzgodnienie czasu i wspólne działanie bez równoległego telefonu."],"correct":3,"feedback":["To pomija ważne kryterium. Formalna obecność nie równa się uważnemu kontaktowi; uogólnianie skutków jednej aktywności.","To pomija ważne kryterium. Formalna obecność nie równa się uważnemu kontaktowi; uogólnianie skutków jednej aktywności.","To pomija ważne kryterium. Formalna obecność nie równa się uważnemu kontaktowi; uogólnianie skutków jednej aktywności.","Prawidłowo. Zapytanie, na czym mu zależy, uzgodnienie czasu i wspólne działanie bez równoległego telefonu."],"root_cause":"Formalna obecność nie równa się uważnemu kontaktowi; uogólnianie skutków jednej aktywności.","evidence":"Zgoda dziecka, brak multitaskingu, krótki uzgodniony rytuał bez oceniania emocji.","severity":"medium","reviewer_profile":"Psycholog więzi rodzic–dziecko","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',9,'{"question":"Po przegranej dziecko rzuca kontrolerem w kierunku rodzeństwa. Która reakcja zachowuje granicę i kontakt?","options":["Wysłuchaj emocji bez przerywania rzucania, by nie nasilać napięcia.","Najpierw zastosuj długą karę, a dopiero potem zapytaj o emocje.","Najpierw zatrzymaj zagrożenie, nazwij emocję bez oceny osoby i porozmawiaj o naprawie, gdy wszyscy są bezpieczni.","Poproś dziecko o przeprosiny, zanim zabezpieczysz inne osoby."],"correct":2,"feedback":["To pomija ważne kryterium. Uznanie emocji bywa błędnie rozumiane jako nieingerowanie w przemoc.","To pomija ważne kryterium. Uznanie emocji bywa błędnie rozumiane jako nieingerowanie w przemoc.","Prawidłowo. Najpierw zatrzymaj zagrożenie, nazwij emocję bez oceny osoby i porozmawiaj o naprawie, gdy wszyscy są bezpieczni.","To pomija ważne kryterium. Uznanie emocji bywa błędnie rozumiane jako nieingerowanie w przemoc."],"root_cause":"Uznanie emocji bywa błędnie rozumiane jako nieingerowanie w przemoc.","evidence":"Bezpieczeństwo, nazwanie emocji, jasna granica, późniejszy plan naprawy.","severity":"high","reviewer_profile":"Specjalista regulacji emocji dzieci","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',10,'{"question":"Dziecko prosi o pomoc przy modelu, ale chce samo dokończyć. Kiedy wskazówka jest lepsza od przejęcia zadania?","options":["Gdy rodzic chce przede wszystkim szybciej skończyć model.","Gdy czynność jest bezpieczna i dziecko może rozwiązać problem po jednej małej podpowiedzi.","Gdy dziecko w ogóle nie ma dostępu do instrukcji ani potrzebnych części.","Gdy próba wymaga niebezpiecznego narzędzia poza jego kompetencją."],"correct":1,"feedback":["To pomija ważne kryterium. Pomoc dorosłego może przejść w wyręczanie albo pozostawienie dziecka bez wsparcia.","Prawidłowo. Gdy czynność jest bezpieczna i dziecko może rozwiązać problem po jednej małej podpowiedzi.","To pomija ważne kryterium. Pomoc dorosłego może przejść w wyręczanie albo pozostawienie dziecka bez wsparcia.","To pomija ważne kryterium. Pomoc dorosłego może przejść w wyręczanie albo pozostawienie dziecka bez wsparcia."],"root_cause":"Pomoc dorosłego może przejść w wyręczanie albo pozostawienie dziecka bez wsparcia.","evidence":"Bezpieczny zakres działania, najmniejsza potrzebna podpowiedź i samokontrola dziecka.","severity":"medium","reviewer_profile":"Pedagog uczenia samodzielności","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',11,'{"question":"Rodzic deklaruje strefę bez telefonów, ale musi mieć dostępność na pilny kontakt medyczny. Które rozwiązanie jest spójne?","options":["Wspólna reguła odkładania ekranów i jawny, wąsko określony wyjątek dla rzeczywiście pilnych połączeń.","Reguła tylko dla dzieci, bo dorośli posiadają obowiązki.","Całkowity zakaz telefonu nawet w sytuacji zagrożenia zdrowia.","Pozostawienie telefonu na stole i odpowiadanie na wszystko, aby nie przegapić nic ważnego."],"correct":0,"feedback":["Prawidłowo. Wspólna reguła odkładania ekranów i jawny, wąsko określony wyjątek dla rzeczywiście pilnych połączeń.","To pomija ważne kryterium. Reguła bez uzasadnionych wyjątków albo nieobowiązująca dorosłych nie daje dobrego wzorca.","To pomija ważne kryterium. Reguła bez uzasadnionych wyjątków albo nieobowiązująca dorosłych nie daje dobrego wzorca.","To pomija ważne kryterium. Reguła bez uzasadnionych wyjątków albo nieobowiązująca dorosłych nie daje dobrego wzorca."],"root_cause":"Reguła bez uzasadnionych wyjątków albo nieobowiązująca dorosłych nie daje dobrego wzorca.","evidence":"Wspólny zapis zasady, wyjątek awaryjny, tygodniowa refleksja bez publicznego oceniania.","severity":"medium","reviewer_profile":"Edukator higieny cyfrowej rodziny","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',12,'{"question":"Dziecko milczy po szkole przez jeden dzień. Jak odróżnić troskę od nadinterpretacji?","options":["Uznać milczenie za dowód, że wydarzyło się coś złego.","Odczytać prywatne wiadomości bez żadnych konkretnych przesłanek.","Zrezygnować ze sprawdzania bezpieczeństwa nawet przy wyraźnych objawach zagrożenia.","Zaproponuj spokojny kontakt później i obserwuj sytuację, reagując adekwatnie na konkretne sygnały zagrożenia."],"correct":3,"feedback":["To pomija ważne kryterium. Jednorazowe zachowanie nie jest diagnozą, lecz troska nie wyklucza adekwatnej reakcji na ryzyko.","To pomija ważne kryterium. Jednorazowe zachowanie nie jest diagnozą, lecz troska nie wyklucza adekwatnej reakcji na ryzyko.","To pomija ważne kryterium. Jednorazowe zachowanie nie jest diagnozą, lecz troska nie wyklucza adekwatnej reakcji na ryzyko.","Prawidłowo. Zaproponuj spokojny kontakt później i obserwuj sytuację, reagując adekwatnie na konkretne sygnały zagrożenia."],"root_cause":"Jednorazowe zachowanie nie jest diagnozą, lecz troska nie wyklucza adekwatnej reakcji na ryzyko.","evidence":"Uważna rozmowa, respektowanie odpoczynku, konkretne objawy wymagające pomocy.","severity":"high","reviewer_profile":"Psycholog konsultacji szkolnych dzieci","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',13,'{"question":"Odbiór dziecka opóźnia się o 30 minut. Rodzice mają napięte relacje. Jak przekazać zmianę?","options":["Poprosić dziecko o wysłanie wiadomości i przedstawienie potwierdzenia.","Poczekać bez żadnej informacji, by nie zaostrzać konfliktu.","Bezpośrednio i możliwie neutralnie między dorosłymi, a przy zagrożeniu przez bezpieczny uzgodniony kanał.","Przekazać zmianę przez innych rodziców w obecności dziecka."],"correct":2,"feedback":["To pomija ważne kryterium. Dziecko może stać się pośrednikiem w konflikcie; bezpośredni kontakt nie zawsze jest bezpieczny.","To pomija ważne kryterium. Dziecko może stać się pośrednikiem w konflikcie; bezpośredni kontakt nie zawsze jest bezpieczny.","Prawidłowo. Bezpośrednio i możliwie neutralnie między dorosłymi, a przy zagrożeniu przez bezpieczny uzgodniony kanał.","To pomija ważne kryterium. Dziecko może stać się pośrednikiem w konflikcie; bezpośredni kontakt nie zawsze jest bezpieczny."],"root_cause":"Dziecko może stać się pośrednikiem w konflikcie; bezpośredni kontakt nie zawsze jest bezpieczny.","evidence":"Potwierdzona godzina, miejsce, kanał bezpieczny dla opiekunów, brak obciążania dziecka.","severity":"high","reviewer_profile":"Mediator rodzinny opieki naprzemiennej","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',14,'{"question":"Rodzic mówi: «Krzyknąłem, ale zdenerwowałeś mnie». Co trzeba poprawić?","options":["Dodać dziecku obowiązek natychmiastowego wybaczenia.","Usunąć usprawiedliwiające «ale», nazwać własny krzyk i zaplanować konkretną zmianę reakcji.","Utrzymać «ale», lecz zmienić je na bardziej łagodny ton.","Zastąpić przeprosiny prezentem, aby dziecko nie wracało do sprawy."],"correct":1,"feedback":["To pomija ważne kryterium. Przeprosiny warunkowe przesuwają odpowiedzialność z dorosłego na dziecko.","Prawidłowo. Usunąć usprawiedliwiające «ale», nazwać własny krzyk i zaplanować konkretną zmianę reakcji.","To pomija ważne kryterium. Przeprosiny warunkowe przesuwają odpowiedzialność z dorosłego na dziecko.","To pomija ważne kryterium. Przeprosiny warunkowe przesuwają odpowiedzialność z dorosłego na dziecko."],"root_cause":"Przeprosiny warunkowe przesuwają odpowiedzialność z dorosłego na dziecko.","evidence":"Nazwanie własnego zachowania, brak obwiniania, obserwowalny krok naprawy.","severity":"high","reviewer_profile":"Specjalista komunikacji naprawczej z dzieckiem","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',15,'{"question":"Nastolatek nie chce stale udostępniać GPS, a rodzic troszczy się o powrót z treningu. Jak uzgodnić bezpieczeństwo?","options":["Uzgodnij godzinę, kontakt przy zmianie planu i jasne działanie awaryjne, uwzględniając wiek oraz rzeczywiste ryzyka.","Wymagaj automatycznego śledzenia każdej godziny niezależnie od sytuacji.","Usuń wszystkie zasady powrotu, ponieważ nastolatek potrzebuje prywatności.","Sprawdź ukradkiem telefon, a później przedstaw śledzenie jako uzgodnioną regułę."],"correct":0,"feedback":["Prawidłowo. Uzgodnij godzinę, kontakt przy zmianie planu i jasne działanie awaryjne, uwzględniając wiek oraz rzeczywiste ryzyka.","To pomija ważne kryterium. Prywatność nie oznacza braku opieki, lecz opieka nie uzasadnia automatycznego nadzoru ukrytego.","To pomija ważne kryterium. Prywatność nie oznacza braku opieki, lecz opieka nie uzasadnia automatycznego nadzoru ukrytego.","To pomija ważne kryterium. Prywatność nie oznacza braku opieki, lecz opieka nie uzasadnia automatycznego nadzoru ukrytego."],"root_cause":"Prywatność nie oznacza braku opieki, lecz opieka nie uzasadnia automatycznego nadzoru ukrytego.","evidence":"Wspólne ustalenia, proporcjonalność ryzyka, plan awaryjny, brak nieuzasadnionego szpiegowania.","severity":"high","reviewer_profile":"Psycholog rozwoju i prywatności nastolatka","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',16,'{"question":"Dziecko ma trzy zaległe zadania; nauczyciel nie wie, czy rozumiało polecenie. Co jest pierwszym działaniem?","options":["Wprowadzenie kary za każdą zaległość przed wyjaśnieniem przyczyny.","Samodzielne wykonanie prac za dziecko, by uniknęło kolejnych ocen.","Uznanie trudności za stałą cechę dziecka na podstawie trzech zadań.","Ustalenie konkretnych barier z dzieckiem i nauczycielem oraz małego, sprawdzalnego następnego kroku."],"correct":3,"feedback":["To pomija ważne kryterium. Brak pracy nie dowodzi braku motywacji ani nie wyklucza trudności w zrozumieniu.","To pomija ważne kryterium. Brak pracy nie dowodzi braku motywacji ani nie wyklucza trudności w zrozumieniu.","To pomija ważne kryterium. Brak pracy nie dowodzi braku motywacji ani nie wyklucza trudności w zrozumieniu.","Prawidłowo. Ustalenie konkretnych barier z dzieckiem i nauczycielem oraz małego, sprawdzalnego następnego kroku."],"root_cause":"Brak pracy nie dowodzi braku motywacji ani nie wyklucza trudności w zrozumieniu.","evidence":"Przykłady poleceń, dostęp do materiałów, plan dostosowania i sprawdzenie postępu.","severity":"medium","reviewer_profile":"Pedagog współpracy rodziny ze szkołą","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',17,'{"question":"Dwoje dzieci chce używać jednego roweru, a jedno ma trening o ustalonej godzinie. Co jest sprawiedliwą procedurą?","options":["Zawsze przyznawać rower starszemu dziecku bez dyskusji.","Zawsze wybierać młodsze dziecko, aby nie czuło się pominięte.","Wysłuchanie obojga, zapisanie ograniczeń czasowych i wspólna zasada kolejności możliwa do sprawdzenia.","Rozstrzygać losowaniem niezależnie od realnego terminu treningu i bezpieczeństwa."],"correct":2,"feedback":["To pomija ważne kryterium. Równość formalna nie zawsze odpowiada realnym ograniczeniom, a etykiety utrwalają konflikt.","To pomija ważne kryterium. Równość formalna nie zawsze odpowiada realnym ograniczeniom, a etykiety utrwalają konflikt.","Prawidłowo. Wysłuchanie obojga, zapisanie ograniczeń czasowych i wspólna zasada kolejności możliwa do sprawdzenia.","To pomija ważne kryterium. Równość formalna nie zawsze odpowiada realnym ograniczeniom, a etykiety utrwalają konflikt."],"root_cause":"Równość formalna nie zawsze odpowiada realnym ograniczeniom, a etykiety utrwalają konflikt.","evidence":"Bezpieczeństwo, dwa opisy, faktyczne terminy, jasna i wykonalna reguła.","severity":"medium","reviewer_profile":"Mediator konfliktów między rodzeństwem","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',18,'{"question":"Dziecka nie przyjęto do drużyny. Czy powiedzenie «za rok na pewno wygrasz» jest właściwe?","options":["Tak, bo mocna obietnica zawsze poprawia motywację.","Nie: uznaj rozczarowanie i rozmawiaj o możliwych działaniach tylko wtedy, gdy dziecko chce, bez gwarantowania wyniku.","Tak, jeśli rodzic zapewni dodatkowe treningi bez pytania dziecka.","Tak, jeśli obietnica będzie wypowiedziana bardzo spokojnie."],"correct":1,"feedback":["To pomija ważne kryterium. Podtrzymywanie motywacji nie daje prawa do obiecywania niekontrolowanego wyniku.","Prawidłowo. Nie: uznaj rozczarowanie i rozmawiaj o możliwych działaniach tylko wtedy, gdy dziecko chce, bez gwarantowania wyniku.","To pomija ważne kryterium. Podtrzymywanie motywacji nie daje prawa do obiecywania niekontrolowanego wyniku.","To pomija ważne kryterium. Podtrzymywanie motywacji nie daje prawa do obiecywania niekontrolowanego wyniku."],"root_cause":"Podtrzymywanie motywacji nie daje prawa do obiecywania niekontrolowanego wyniku.","evidence":"Uznanie uczuć, pytanie o gotowość, realistyczne opcje i prawo do rezygnacji.","severity":"medium","reviewer_profile":"Psycholog motywacji młodzieży w sporcie","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('lepszy-tata',19,'{"question":"Plan kontaktu zakładał spacery, lecz dziecko prosi o gotowanie. Co sprawdzić przed korektą?","options":["Czy wspólne gotowanie jest bezpieczne i chciane przez dziecko, a rytuał uważnego kontaktu może zostać zachowany.","Pozostać przy spacerach, ponieważ plan 90-dniowy nie podlega korekcie.","Uznać cały miesiąc spacerów za nieważny i przerwać regularne spotkania.","Zamienić spacer na obowiązkowe gotowanie z oceną zaangażowania dziecka."],"correct":0,"feedback":["Prawidłowo. Czy wspólne gotowanie jest bezpieczne i chciane przez dziecko, a rytuał uważnego kontaktu może zostać zachowany.","To pomija ważne kryterium. Sztywność planu może zmieniać relację w narzędzie kontroli dziecka.","To pomija ważne kryterium. Sztywność planu może zmieniać relację w narzędzie kontroli dziecka.","To pomija ważne kryterium. Sztywność planu może zmieniać relację w narzędzie kontroli dziecka."],"root_cause":"Sztywność planu może zmieniać relację w narzędzie kontroli dziecka.","evidence":"Zgoda na zmianę, bezpieczny zakres czynności, obserwacja własnej dostępności.","severity":"medium","reviewer_profile":"Trener umiejętności rodzicielskich i ewaluacji nawyków","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',12,'{"question":"Rano kuchnia jest brudna, chociaż każdy wieczorem mówi «gotowe». Jak udowodnić poprawę bez szukania winnego?","options":["Kupić nowe pojemniki bez sprawdzenia źródła problemu.","Dodać ostrzejszą karę za pozostawienie naczyń.","Porównywać domowników według liczby minut sprzątania.","Zdefiniować widoczny stan końcowy i zmierzyć przez tydzień, czy po kolacji jest osiągany."],"correct":3,"feedback":["To pomija ważne kryterium. Brak mierzalnego standardu i automatyczne przypisywanie winy.","To pomija ważne kryterium. Brak mierzalnego standardu i automatyczne przypisywanie winy.","To pomija ważne kryterium. Brak mierzalnego standardu i automatyczne przypisywanie winy.","Prawidłowo. Zdefiniować widoczny stan końcowy i zmierzyć przez tydzień, czy po kolacji jest osiągany."],"root_cause":"Brak mierzalnego standardu i automatyczne przypisywanie winy.","evidence":"Lista stanu końcowego, obserwacje przez tydzień, korekta środowiska i podziału pracy.","severity":"medium","reviewer_profile":"Projektant procesów porządkowych w domu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',13,'{"question":"Jedna osoba sprząta, druga planuje zakupy i pilnuje terminów. Czy podział «po jednym zadaniu» jest sprawiedliwy?","options":["Tak, liczba widocznych zadań obu osób jest taka sama.","Tak, jeśli tylko sprzątanie zajmuje tyle samo czasu.","Nie da się ocenić bez uwzględnienia pracy planowania, pamiętania i monitorowania zadania.","Nie, jeśli jedna osoba nie wykonuje każdej czynności fizycznie."],"correct":2,"feedback":["To pomija ważne kryterium. Praca organizacyjna może pozostać niewidzialna przy liczeniu tylko wykonania.","To pomija ważne kryterium. Praca organizacyjna może pozostać niewidzialna przy liczeniu tylko wykonania.","Prawidłowo. Nie da się ocenić bez uwzględnienia pracy planowania, pamiętania i monitorowania zadania.","To pomija ważne kryterium. Praca organizacyjna może pozostać niewidzialna przy liczeniu tylko wykonania."],"root_cause":"Praca organizacyjna może pozostać niewidzialna przy liczeniu tylko wykonania.","evidence":"Karta właściciela zadania: plan, zakupy, wykonanie, weryfikacja i realny czas.","severity":"medium","reviewer_profile":"Psycholog podziału obciążenia mentalnego","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',14,'{"question":"Wyjście 7:30, czynności trwają 35 min i potrzeba 10 min buforu. Godzina startu?","options":["6:55, bo bufor dodaje się do godziny wyjścia.","6:45; następnie zweryfikuj, które czynności są sekwencyjne, a które można wykonać równolegle.","7:05, bo czynności i bufor można zawsze nałożyć.","6:45 gwarantuje bezstresowy poranek niezależnie od zdarzeń."],"correct":1,"feedback":["To pomija ważne kryterium. Błąd rachunku czasu albo traktowanie założenia jako gwarancji.","Prawidłowo. 6:45; następnie zweryfikuj, które czynności są sekwencyjne, a które można wykonać równolegle.","To pomija ważne kryterium. Błąd rachunku czasu albo traktowanie założenia jako gwarancji.","To pomija ważne kryterium. Błąd rachunku czasu albo traktowanie założenia jako gwarancji."],"root_cause":"Błąd rachunku czasu albo traktowanie założenia jako gwarancji.","evidence":"Oś czasu, rzeczywiste pomiary, bufor i dwie czynności przygotowane wcześniej.","severity":"medium","reviewer_profile":"Specjalista planowania czasu rodziny","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',15,'{"question":"Jedno z rodziców choruje. Jak wybierzesz priorytety z listy 10 zadań?","options":["Najpierw higiena, bezpieczne jedzenie i opieka; resztę rozdziel lub odrocz według możliwości.","Wykonanie wszystkich prac jest konieczne, choćby kosztem odpoczynku.","Wszystkie obowiązki należy przekazać najstarszemu dziecku.","Można odroczyć wszystko, w tym bezpieczeństwo żywności i opiekę."],"correct":0,"feedback":["Prawidłowo. Najpierw higiena, bezpieczne jedzenie i opieka; resztę rozdziel lub odrocz według możliwości.","To pomija ważne kryterium. Brak hierarchii zadań i narzucanie nierealnej liczby obowiązków.","To pomija ważne kryterium. Brak hierarchii zadań i narzucanie nierealnej liczby obowiązków.","To pomija ważne kryterium. Brak hierarchii zadań i narzucanie nierealnej liczby obowiązków."],"root_cause":"Brak hierarchii zadań i narzucanie nierealnej liczby obowiązków.","evidence":"Wersja minimum, przydział zależny od możliwości, warunki odroczenia.","severity":"high","reviewer_profile":"Koordynator rodzinnych planów awaryjnych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',16,'{"question":"Na półce stoi odkamieniacz i produkt chlorowy. Czy można je połączyć dla lepszego działania?","options":["Tak, ale wyłącznie w dobrze wentylowanym pomieszczeniu.","Tak, jeśli ilość obu substancji jest niewielka.","Tak, jeśli mieszankę od razu spłucze się wodą.","Nie. Nie mieszaj takich środków; stosuj etykiety i zasady przechowywania, a w razie uwolnienia gazu opuść zagrożone miejsce i wezwij pomoc."],"correct":3,"feedback":["To pomija ważne kryterium. Powstanie toksycznych gazów przy mieszaniu niektórych środków chlorowych i kwasowych.","To pomija ważne kryterium. Powstanie toksycznych gazów przy mieszaniu niektórych środków chlorowych i kwasowych.","To pomija ważne kryterium. Powstanie toksycznych gazów przy mieszaniu niektórych środków chlorowych i kwasowych.","Prawidłowo. Nie. Nie mieszaj takich środków; stosuj etykiety i zasady przechowywania, a w razie uwolnienia gazu opuść zagrożone miejsce i wezwij pomoc."],"root_cause":"Powstanie toksycznych gazów przy mieszaniu niektórych środków chlorowych i kwasowych.","evidence":"Oryginalne opakowania, ostrzeżenia na etykietach, dostęp dzieci, wentylacja i procedura awaryjna.","severity":"critical","reviewer_profile":"Ekspert bezpiecznej chemii gospodarczej","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',17,'{"question":"Dziecko przy nakrywaniu stołu zapomniało łyżek. Jak zareagować, by nauczyć samokontroli?","options":["Odebrać zadanie na stałe po pierwszej pomyłce.","Wymagać, aby rodzeństwo oceniało je publicznie.","Pokazać kryterium kompletnego nakrycia i pozwolić spokojnie uzupełnić brak, bez zawstydzania.","Pochwalić bez zwracania uwagi na brakujące elementy."],"correct":2,"feedback":["To pomija ważne kryterium. Brak informacji zwrotnej albo używanie zawstydzania zamiast nauki.","To pomija ważne kryterium. Brak informacji zwrotnej albo używanie zawstydzania zamiast nauki.","Prawidłowo. Pokazać kryterium kompletnego nakrycia i pozwolić spokojnie uzupełnić brak, bez zawstydzania.","To pomija ważne kryterium. Brak informacji zwrotnej albo używanie zawstydzania zamiast nauki."],"root_cause":"Brak informacji zwrotnej albo używanie zawstydzania zamiast nauki.","evidence":"Prosta karta kontroli zadania, dostosowanie do możliwości i bezpieczeństwo.","severity":"medium","reviewer_profile":"Pedagog obowiązków dopasowanych do wieku","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',18,'{"question":"750 ml środka kosztuje 15 zł, a litr 18 zł. Jaki wniosek jest dokładny?","options":["Pierwszy jest tańszy, bo ma niższą cenę na półce.","Pierwszy kosztuje 20 zł/l, drugi 18 zł/l; oszczędność wymaga jeszcze realnego zużycia i przechowywania.","Drugi jest zawsze opłacalny, nawet gdy zostanie wyrzucony.","Oba mają tę samą cenę jednostkową, bo różnica wynosi tylko 3 zł."],"correct":1,"feedback":["To pomija ważne kryterium. Mylenie ceny opakowania z ceną jednostkową i ekonomią użycia.","Prawidłowo. Pierwszy kosztuje 20 zł/l, drugi 18 zł/l; oszczędność wymaga jeszcze realnego zużycia i przechowywania.","To pomija ważne kryterium. Mylenie ceny opakowania z ceną jednostkową i ekonomią użycia.","To pomija ważne kryterium. Mylenie ceny opakowania z ceną jednostkową i ekonomią użycia."],"root_cause":"Mylenie ceny opakowania z ceną jednostkową i ekonomią użycia.","evidence":"Działania 15/0,75 i 18/1, przydatność i warunki składowania.","severity":"medium","reviewer_profile":"Ekonomista kosztów eksploatacji domu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('obowiazki-domowe',19,'{"question":"Odsetek wykonania wzrósł z 60 do 83%, ale jedna osoba jest przeciążona. Czy plan zaliczyć jako sukces?","options":["Jest poprawa wykonania, lecz trzeba też ocenić podział obowiązków i koszt dla domowników.","Tak, bo procent jest wyższy bez potrzeby innej oceny.","Nie, ponieważ każda poprawa wymaga 100% wykonania.","Nie da się ocenić niczego bez porównywania charakterów osób."],"correct":0,"feedback":["Prawidłowo. Jest poprawa wykonania, lecz trzeba też ocenić podział obowiązków i koszt dla domowników.","To pomija ważne kryterium. Wynik liczbowy bez mierzenia kosztów i sprawiedliwości podziału.","To pomija ważne kryterium. Wynik liczbowy bez mierzenia kosztów i sprawiedliwości podziału.","To pomija ważne kryterium. Wynik liczbowy bez mierzenia kosztów i sprawiedliwości podziału."],"root_cause":"Wynik liczbowy bez mierzenia kosztów i sprawiedliwości podziału.","evidence":"Dane wykonania, czas pracy, przypominanie, możliwość korekty i opinia domowników.","severity":"medium","reviewer_profile":"Audytor ergonomii i sprawiedliwości podziału obowiązków","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('plecionkarz',16,'{"question":"Kosz zakupowy wykonano z wikliny dobranej tylko po kolorze. Co trzeba udowodnić przed podaniem nośności?","options":["Wystarczy sprawdzić grubość jednego pręta obrzeża.","Wystarczy potwierdzić, że pręty są równego koloru.","Wystarczy test, że pusty kosz sam stoi na podłodze.","Stan materiału, konstrukcję dna, obrzeże, uchwyt i sposób użytkowania zweryfikowane odpowiednią kontrolą."],"correct":3,"feedback":["To pomija ważne kryterium. Estetyka materiału nie jest dowodem nośności konstrukcji.","To pomija ważne kryterium. Estetyka materiału nie jest dowodem nośności konstrukcji.","To pomija ważne kryterium. Estetyka materiału nie jest dowodem nośności konstrukcji.","Prawidłowo. Stan materiału, konstrukcję dna, obrzeże, uchwyt i sposób użytkowania zweryfikowane odpowiednią kontrolą."],"root_cause":"Estetyka materiału nie jest dowodem nośności konstrukcji.","evidence":"Dobór prętów do funkcji, uchwyt, splot, protokół odpowiedniej próby.","severity":"high","reviewer_profile":"Mistrz doboru wikliny i konstrukcji splotu","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('plecionkarz',17,'{"question":"Kosz ma średnice 300 i 318 mm w dwóch kierunkach. Czy «18 mm jest mało» wystarcza do akceptacji?","options":["Tak, bo zdjęcie wykonane z przodu nie pokazuje różnicy.","Tak, jeśli oba wymiary zaokrągli się do 31 cm.","Nie: sprawdź szablon i uzgodnione tolerancje przed decyzją, a korektę rozważ przed zamknięciem splotu.","Tak, jeśli uchwyt jest centralnie umieszczony."],"correct":2,"feedback":["To pomija ważne kryterium. Własne uznaniowe tolerancje zamiast wymogów zamówienia.","To pomija ważne kryterium. Własne uznaniowe tolerancje zamiast wymogów zamówienia.","Prawidłowo. Nie: sprawdź szablon i uzgodnione tolerancje przed decyzją, a korektę rozważ przed zamknięciem splotu.","To pomija ważne kryterium. Własne uznaniowe tolerancje zamiast wymogów zamówienia."],"root_cause":"Własne uznaniowe tolerancje zamiast wymogów zamówienia.","evidence":"Miejsca pomiarów, szablon, średnice, wysokość i kryterium odbioru.","severity":"high","reviewer_profile":"Kontroler geometrii wyrobów plecionkarskich","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('plecionkarz',18,'{"question":"Kosz ma pęknięty uchwyt i podejrzany nalot przy dnie. Jak rozdzielić problemy?","options":["Naprawić uchwyt i uznać kosz za bezpieczny bez oględzin dna.","Zabezpieczyć produkt, osobno ocenić połączenie konstrukcyjne i ryzyko higieniczne; nie ukrywać nalotu klejem.","Wytrzeć nalot i automatycznie dopuścić do kontaktu z żywnością.","Suszyć uchwyt bez sprawdzenia wątku i obrzeża."],"correct":1,"feedback":["To pomija ważne kryterium. Zbiorcze «naprawione» maskuje różne ryzyka użytkowe i higieniczne.","Prawidłowo. Zabezpieczyć produkt, osobno ocenić połączenie konstrukcyjne i ryzyko higieniczne; nie ukrywać nalotu klejem.","To pomija ważne kryterium. Zbiorcze «naprawione» maskuje różne ryzyka użytkowe i higieniczne.","To pomija ważne kryterium. Zbiorcze «naprawione» maskuje różne ryzyka użytkowe i higieniczne."],"root_cause":"Zbiorcze «naprawione» maskuje różne ryzyka użytkowe i higieniczne.","evidence":"Dokumentacja konstrukcji, wilgotność, oględziny, przeznaczenie i decyzja.","severity":"high","reviewer_profile":"Konserwator wyrobów z włókien roślinnych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('plecionkarz',19,'{"question":"Klient chce przenosić narzędzia w koszu zaprojektowanym jako dekoracja. Czy można dopisać «do 10 kg»?","options":["Nie bez projektu i odpowiedniej weryfikacji połączeń oraz nośności dla nowego przeznaczenia.","Tak, jeżeli klient podpisze, że bierze odpowiedzialność.","Tak, jeśli podobny kosz sprzedawany jest jako transportowy.","Tak, jeśli wymieni się tylko rękojeść na grubszą."],"correct":0,"feedback":["Prawidłowo. Nie bez projektu i odpowiedniej weryfikacji połączeń oraz nośności dla nowego przeznaczenia.","To pomija ważne kryterium. Deklarowanie udźwigu bez dowodów albo przerzucanie ryzyka na klienta.","To pomija ważne kryterium. Deklarowanie udźwigu bez dowodów albo przerzucanie ryzyka na klienta.","To pomija ważne kryterium. Deklarowanie udźwigu bez dowodów albo przerzucanie ryzyka na klienta."],"root_cause":"Deklarowanie udźwigu bez dowodów albo przerzucanie ryzyka na klienta.","evidence":"Specyfikacja obciążeń, konstrukcja, adekwatna próba, ograniczenia użycia.","severity":"high","reviewer_profile":"Projektant bezpiecznych wyrobów wiklinowych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',8,'{"question":"Nieśmiałe dziecko trzyma opiekuna za rękę, a grupa jest podekscytowana. Jak rozpocząć bez presji?","options":["Podejść do dziecka, bo reszta już się bawi.","Poprosić opiekuna o delikatne przesunięcie dziecka do przodu.","Skupić na dziecku uwagę grupy, aby zachęcić je do kontaktu.","Powitać spokojnie całą grupę i zostawić dziecku wybór obserwacji lub późniejszego dołączenia."],"correct":3,"feedback":["To pomija ważne kryterium. Naruszenie granic dziecka w celu wymuszenia udziału.","To pomija ważne kryterium. Naruszenie granic dziecka w celu wymuszenia udziału.","To pomija ważne kryterium. Naruszenie granic dziecka w celu wymuszenia udziału.","Prawidłowo. Powitać spokojnie całą grupę i zostawić dziecku wybór obserwacji lub późniejszego dołączenia."],"root_cause":"Naruszenie granic dziecka w celu wymuszenia udziału.","evidence":"Możliwość odmowy, brak przymusu dotyku, miejsce przy opiekunie.","severity":"high","reviewer_profile":"Pedagog animacji dziecięcej i bezpiecznego powitania","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',9,'{"question":"Dziecko mówi, że ma mniejszy prezent od kolegi. Co byłoby bezpiecznym rozwiązaniem?","options":["Publicznie przedstaw budżety wszystkich paczek, by pokazać zasady.","Obiecaj większą paczkę bez ustalenia z organizatorem.","Uznaj uczucie, nie porównuj wartości dzieci i dyskretnie zweryfikuj przypisanie paczki z opiekunem.","Poproś inne dzieci o pokazanie swoich prezentów dla porównania."],"correct":2,"feedback":["To pomija ważne kryterium. Rankingi dzieci według prezentów i łamanie poufności rodzin.","To pomija ważne kryterium. Rankingi dzieci według prezentów i łamanie poufności rodzin.","Prawidłowo. Uznaj uczucie, nie porównuj wartości dzieci i dyskretnie zweryfikuj przypisanie paczki z opiekunem.","To pomija ważne kryterium. Rankingi dzieci według prezentów i łamanie poufności rodzin."],"root_cause":"Rankingi dzieci według prezentów i łamanie poufności rodzin.","evidence":"Neutralne komunikaty, identyfikacja paczek, dyskrecja.","severity":"medium","reviewer_profile":"Specjalista zapobiegania wykluczeniu dzieci","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',10,'{"question":"Dziecko nie mówi, ale może wskazać kartę. Czy brak odpowiedzi to zgoda na bliski kontakt?","options":["Tak, jeżeli opiekun zapewnia, że dziecko rozumie.","Nie. Zaproponuj możliwość wyboru gestem i czas, respektując także brak decyzji i rezygnację.","Tak, jeśli pytanie zostanie powtórzone głośniej.","Tak, jeśli reszta grupy już odebrała prezenty."],"correct":1,"feedback":["To pomija ważne kryterium. Milczenie nie oznacza przyzwolenia ani braku rozumienia.","Prawidłowo. Nie. Zaproponuj możliwość wyboru gestem i czas, respektując także brak decyzji i rezygnację.","To pomija ważne kryterium. Milczenie nie oznacza przyzwolenia ani braku rozumienia.","To pomija ważne kryterium. Milczenie nie oznacza przyzwolenia ani braku rozumienia."],"root_cause":"Milczenie nie oznacza przyzwolenia ani braku rozumienia.","evidence":"Preferowana forma AAC, uzgodnienie z opiekunem, czas i prawo odmowy.","severity":"high","reviewer_profile":"Specjalista komunikacji alternatywnej i wspomagającej AAC","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',11,'{"question":"Rodzic zgodził się na fotografię dla rodziny, a organizator chce ją wrzucić publicznie. Co trzeba sprawdzić?","options":["Osobną, uprzednią i konkretną podstawę publikacji, zgodną z celem oraz uwzględniającą zdanie dziecka.","Wystarczy, że na zdjęciu nie ma nazwiska.","Wystarczy poinformować o możliwości usunięcia już po publikacji.","Wystarczy regulamin udziału w imprezie bez zgody na rozpowszechnianie."],"correct":0,"feedback":["Prawidłowo. Osobną, uprzednią i konkretną podstawę publikacji, zgodną z celem oraz uwzględniającą zdanie dziecka.","To pomija ważne kryterium. Zgoda na zdjęcie prywatne nie upoważnia automatycznie do publikacji.","To pomija ważne kryterium. Zgoda na zdjęcie prywatne nie upoważnia automatycznie do publikacji.","To pomija ważne kryterium. Zgoda na zdjęcie prywatne nie upoważnia automatycznie do publikacji."],"root_cause":"Zgoda na zdjęcie prywatne nie upoważnia automatycznie do publikacji.","evidence":"Cel, platforma, podmiot, czas, uprzednia zgoda i interes dziecka.","severity":"critical","reviewer_profile":"Inspektor ochrony danych i wizerunku małoletnich","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://uodo.gov.pl/pl/644/4111","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',12,'{"question":"Dziecko podczas wizyty przedszkolnej chce wyjść z sali. Kto ustala bezpieczny sposób?","options":["Animator wyprowadza dziecko sam, aby przyspieszyć program.","Cały personel wychodzi z jednym dzieckiem, pozostawiając grupę bez nadzoru.","Dziecko opuszcza salę samo bez powiadomienia personelu.","Wyznaczony personel placówki, koordynując nadzór nad grupą; animator nie przejmuje roli opiekuna."],"correct":3,"feedback":["To pomija ważne kryterium. Przekroczenie kompetencji animatora i brak nadzoru nad grupą.","To pomija ważne kryterium. Przekroczenie kompetencji animatora i brak nadzoru nad grupą.","To pomija ważne kryterium. Przekroczenie kompetencji animatora i brak nadzoru nad grupą.","Prawidłowo. Wyznaczony personel placówki, koordynując nadzór nad grupą; animator nie przejmuje roli opiekuna."],"root_cause":"Przekroczenie kompetencji animatora i brak nadzoru nad grupą.","evidence":"Ustalone role, zasady przekazania, nadzór placówki.","severity":"critical","reviewer_profile":"Koordynator ochrony dzieci w placówkach edukacyjnych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',13,'{"question":"Głośna muzyka powoduje, że dziecko zakrywa uszy. Jaka reakcja nie wymaga diagnozy?","options":["Wytłumaczyć, że utwór potrwa tylko pół minuty.","Przenieść dziecko bliżej animatora bez zmiany muzyki.","Ściszyć lub wyłączyć dźwięk, umożliwić przerwę z opiekunem i nie wymuszać powrotu.","Czekać z wyłączeniem, aż dziecko zgodzi się wrócić."],"correct":2,"feedback":["To pomija ważne kryterium. Zignorowanie widocznego dyskomfortu lub wymuszanie ekspozycji.","To pomija ważne kryterium. Zignorowanie widocznego dyskomfortu lub wymuszanie ekspozycji.","Prawidłowo. Ściszyć lub wyłączyć dźwięk, umożliwić przerwę z opiekunem i nie wymuszać powrotu.","To pomija ważne kryterium. Zignorowanie widocznego dyskomfortu lub wymuszanie ekspozycji."],"root_cause":"Zignorowanie widocznego dyskomfortu lub wymuszanie ekspozycji.","evidence":"Sygnały dyskomfortu, możliwość wyciszenia, dostępna alternatywa.","severity":"high","reviewer_profile":"Terapeuta integracji sensorycznej — projektowanie spokojnego udziału","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',14,'{"question":"Dziecko prosi o obietnicę powrotu nieobecnego taty. Jak uniknąć krzywdzącej obietnicy?","options":["Zapewnij, że magia świąt może sprowadzić tatę, jeśli dziecko będzie grzeczne.","Uznaj tęsknotę, powiedz uczciwie, że nie możesz tego zagwarantować, i zaoferuj kontakt z zaufanym opiekunem.","Przy wszystkich pytaj szczegółowo, dlaczego tata jest nieobecny.","Zastąp rozmowę dodatkowym prezentem bez pytania o potrzebę."],"correct":1,"feedback":["To pomija ważne kryterium. Bezpodstawne obietnice i przenoszenie odpowiedzialności na dziecko.","Prawidłowo. Uznaj tęsknotę, powiedz uczciwie, że nie możesz tego zagwarantować, i zaoferuj kontakt z zaufanym opiekunem.","To pomija ważne kryterium. Bezpodstawne obietnice i przenoszenie odpowiedzialności na dziecko.","To pomija ważne kryterium. Bezpodstawne obietnice i przenoszenie odpowiedzialności na dziecko."],"root_cause":"Bezpodstawne obietnice i przenoszenie odpowiedzialności na dziecko.","evidence":"Uznanie emocji, brak gwarancji, poufność i opiekun.","severity":"high","reviewer_profile":"Psycholog komunikacji wspierającej dziecko w kryzysie","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',15,'{"question":"Starsze dziecko rozpoznaje głos sąsiada w kostiumie. Co zrobić bez manipulowania?","options":["Potraktować obserwację poważnie i zaprosić do wspólnej zabawy bez wymuszania tajemnicy.","Obiecać dodatkowy prezent za nierozpowiadanie o odkryciu.","Poinformować grupę, że dziecko próbuje zepsuć zabawę.","Wymagać publicznego potwierdzenia wersji animatora."],"correct":0,"feedback":["Prawidłowo. Potraktować obserwację poważnie i zaprosić do wspólnej zabawy bez wymuszania tajemnicy.","To pomija ważne kryterium. Zawstydzanie lub nagradzanie milczenia o rozpoznaniu kostiumu.","To pomija ważne kryterium. Zawstydzanie lub nagradzanie milczenia o rozpoznaniu kostiumu.","To pomija ważne kryterium. Zawstydzanie lub nagradzanie milczenia o rozpoznaniu kostiumu."],"root_cause":"Zawstydzanie lub nagradzanie milczenia o rozpoznaniu kostiumu.","evidence":"Neutralna rozmowa, poszanowanie rodzinnych zwyczajów, brak presji.","severity":"medium","reviewer_profile":"Pedagog zabawy symbolicznej i różnic wieku","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',16,'{"question":"Do zajęć używany jest papier z odzysku, ale część opakowań ma zszywki. Co zrobisz?","options":["Pozostawisz zszywki, jeśli dzieci mają więcej niż pięć lat.","Wyłączysz wszystkie materiały z odzysku bez oceny ich stanu.","Każdemu dziecku dasz nowe przybory jako warunek udziału.","Wyłączysz niebezpieczne elementy, sprawdzisz czystość i wiek uczestników, przygotowując równoległą opcję udziału."],"correct":3,"feedback":["To pomija ważne kryterium. Ekologiczne pochodzenie materiału nie zastępuje kontroli bezpieczeństwa.","To pomija ważne kryterium. Ekologiczne pochodzenie materiału nie zastępuje kontroli bezpieczeństwa.","To pomija ważne kryterium. Ekologiczne pochodzenie materiału nie zastępuje kontroli bezpieczeństwa.","Prawidłowo. Wyłączysz niebezpieczne elementy, sprawdzisz czystość i wiek uczestników, przygotowując równoległą opcję udziału."],"root_cause":"Ekologiczne pochodzenie materiału nie zastępuje kontroli bezpieczeństwa.","evidence":"Czystość, ostre elementy, wiek, dostępność aktywności.","severity":"medium","reviewer_profile":"Edukator ekologiczny materiałów bezpiecznych dla dzieci","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',17,'{"question":"Dziecko upadło, ma silny ból i nie wstaje. Czy animator powinien przenieść je na krzesło?","options":["Tak, żeby zrobić miejsce na dalszy program.","Tak, jeśli dwie dorosłe osoby są wystarczająco silne.","Nie rutynowo: zabezpiecz grupę, wezwij odpowiednią pomoc i nie przemieszczaj, jeśli nie jest to konieczne dla bezpieczeństwa.","Tak, bo siedzenie zawsze ułatwia obserwację urazu."],"correct":2,"feedback":["To pomija ważne kryterium. Nieuzasadnione przemieszczanie poszkodowanego i opóźnienie wezwania pomocy.","To pomija ważne kryterium. Nieuzasadnione przemieszczanie poszkodowanego i opóźnienie wezwania pomocy.","Prawidłowo. Nie rutynowo: zabezpiecz grupę, wezwij odpowiednią pomoc i nie przemieszczaj, jeśli nie jest to konieczne dla bezpieczeństwa.","To pomija ważne kryterium. Nieuzasadnione przemieszczanie poszkodowanego i opóźnienie wezwania pomocy."],"root_cause":"Nieuzasadnione przemieszczanie poszkodowanego i opóźnienie wezwania pomocy.","evidence":"Strefa bezpieczeństwa, odpowiednia pomoc, instrukcje służb, dokumentacja zdarzenia.","severity":"critical","reviewer_profile":"Instruktor reagowania na zdarzenia i pierwszej pomocy dzieciom","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://www.gov.pl/web/poradnikbezpieczenstwa/pierwsza-pomoc","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',18,'{"question":"Wizytę skrócono do 10 minut, paczki zajmują 8. Jaka zmiana jest racjonalna?","options":["Skrócić wydawanie do 4 minut kosztem kontroli odbiorców.","Zachować krótkie powitanie, spokojne wydanie paczek i zakończenie; zrezygnować z piosenki i zdjęć.","Zachować zdjęcia, a prezenty wydać zbiorowo bez identyfikacji.","Przenieść powitanie i zakończenie po wszystkich zdjęciach."],"correct":1,"feedback":["To pomija ważne kryterium. Spieszenie się kosztem bezpieczeństwa i prawidłowej identyfikacji.","Prawidłowo. Zachować krótkie powitanie, spokojne wydanie paczek i zakończenie; zrezygnować z piosenki i zdjęć.","To pomija ważne kryterium. Spieszenie się kosztem bezpieczeństwa i prawidłowej identyfikacji.","To pomija ważne kryterium. Spieszenie się kosztem bezpieczeństwa i prawidłowej identyfikacji."],"root_cause":"Spieszenie się kosztem bezpieczeństwa i prawidłowej identyfikacji.","evidence":"Czas wręczania, przydział opiekunów i nieobowiązkowe dodatki.","severity":"medium","reviewer_profile":"Planista logistyki wydarzeń dziecięcych","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":null,"human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb),
('swiety-mikolaj',19,'{"question":"Dziecko odmawia wspólnego zdjęcia, lecz chce otrzymać paczkę. Jakie rozwiązanie chroni jego prawa?","options":["Zapewnić wydanie prezentu poza kadrem, a zdjęcie ograniczyć do chętnych lub scenografii.","Wstrzymać prezent do czasu uzyskania zgody na zdjęcie.","Zrobić ujęcie całości i później ewentualnie wyciąć dziecko.","Poprosić resztę grupy, aby przekonała dziecko do zdjęcia."],"correct":0,"feedback":["Prawidłowo. Zapewnić wydanie prezentu poza kadrem, a zdjęcie ograniczyć do chętnych lub scenografii.","To pomija ważne kryterium. Warunkowanie uczestnictwa zgodą na rozpowszechnianie wizerunku.","To pomija ważne kryterium. Warunkowanie uczestnictwa zgodą na rozpowszechnianie wizerunku.","To pomija ważne kryterium. Warunkowanie uczestnictwa zgodą na rozpowszechnianie wizerunku."],"root_cause":"Warunkowanie uczestnictwa zgodą na rozpowszechnianie wizerunku.","evidence":"Rzeczywista możliwość odmowy, ustalenia z opiekunem, dokumentacja publikacji.","severity":"critical","reviewer_profile":"Audytor standardów imprez i prawa dziecka do odmowy","review_version":"2026-11-17-adversarial-v3","review_method":"adversarial-simulated-professional-perspective","verified_reference_url":"https://uodo.gov.pl/pl/138/3720","human_approved":false,"is_independent_human_review":false,"distinct_from_required_quiz":true}'::jsonb)
), audit AS (
UPDATE public.ta_lessons l SET material=l.material || jsonb_build_object('redteam_quiz',c.redteam,'redteam_audit_revision','2026-11-17-adversarial-v3',
'sections',coalesce(l.material->'sections','[]'::jsonb)||jsonb_build_array(jsonb_build_object('heading','Kontrola krytyczna — czego łatwo nie zauważyć','text','Wątpliwość wymagającego egzaminatora: '||(c.redteam->>'root_cause')||' Potwierdzenie potrzebne do decyzji: '||(c.redteam->>'evidence')||' Rozwiąż dodatkowy test krytyczny, zanim uznasz temat za opanowany.'))),updated_at=now()
FROM cases c
WHERE l.course_slug=c.course_slug AND l.lesson_no=c.lesson_no AND l.material->>'editorial_status'='needs_expert_review' AND l.material->>'redteam_audit_revision' IS DISTINCT FROM '2026-11-17-adversarial-v3'
RETURNING l.course_slug,l.lesson_no)
SELECT count(*) updated,count(distinct course_slug) courses FROM audit;
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Dopuszczenie do kontaktu z żywnością wymaga oceny całego wyrobu, w tym drewna, powłok, klejów i przewidywanych warunków użycia. Przepisy ogólne WE 1935/2004 i wymogi dobrej praktyki WE 2023/2006 są punktem odniesienia dla odpowiednich materiałów i wyrobów; sama szczelność nie stanowi dowodu bezpieczeństwa. Nie deklaruj zgodności bez identyfikowalnej dokumentacji.","source_url":"https://www.gov.pl/web/gis/materialy-i-wyroby-przeznaczone-do-konaktu-z-zywnoscia","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='bednarz' AND lesson_no=18 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Według Arbeidstilsynet ryzyko pracy na wysokości należy ocenić dla konkretnego zadania, preferując zabezpieczenia zbiorowe przed środkami ochrony indywidualnej. Podnośnik musi być używany zgodnie z instrukcją producenta i przez osoby z udokumentowanym szkoleniem. Przy ciężkiej tafli nie należy zastępować planu transportu zwykłą drabiną.","source_url":"https://www.arbeidstilsynet.no/risikofylt-arbeid/arbeid-i-hoyden/","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='brygadzista' AND lesson_no=13 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Ochrona konsumenta z tytułu niezgodności towaru z umową co do zasady dotyczy zakupu od przedsiębiorcy. W sprzedaży od osoby prywatnej kupujący nie staje się z tego powodu konsumentem. Komis może być sprzedawcą albo pośrednikiem — konieczne jest ustalenie rzeczywistej strony i charakteru transakcji, a nie tylko miejsca wystawienia pojazdu.","source_url":"https://prawakonsumenta.uokik.gov.pl/pytania-i-odpowiedzi/zagadnienia-ogolne/","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='jak-kupic-samochod' AND lesson_no=17 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"W Polsce standardowy termin złożenia wniosku o rejestrację wynosi 30 dni od nabycia pojazdu. W przypadku spadku termin 60 dni liczy się od prawomocnego orzeczenia stwierdzającego nabycie spadku albo sporządzenia aktu poświadczenia dziedziczenia; dla przedsiębiorcy zajmującego się obrotem pojazdami przewidziano 90 dni. Są wyjątki. Nie utożsamiaj złożenia wniosku z otrzymaniem dowodu rejestracyjnego w tym terminie.","source_url":"https://www.gov.pl/web/infrastruktura/rejestracja-pojazdow","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='jak-kupic-samochod' AND lesson_no=18 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"UODO wskazuje, że zgoda na publikację rozpoznawalnego wizerunku dziecka powinna być dobrowolna, uprzednia, precyzyjna, odnosić się do konkretnego celu, kanału i podmiotu oraz oznaczonego czasu. Udział w wydarzeniu i uzgodnione zdjęcie rodzinne nie oznaczają automatycznie zgody na publiczną publikację; trzeba respektować zdanie dziecka odpowiednio do wieku.","source_url":"https://uodo.gov.pl/pl/644/4111","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='swiety-mikolaj' AND lesson_no=11 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Dziecko, które nie chce być na zdjęciu, nadal może uczestniczyć w zabawie i odebrać prezent. UODO przestrzega przed łączeniem prawa udziału z przymusową zgodą na rozpowszechnianie wizerunku; organizator powinien przewidzieć realną możliwość udziału poza kadrem.","source_url":"https://uodo.gov.pl/pl/138/3720","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='swiety-mikolaj' AND lesson_no=19 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Oficjalny poradnik pierwszej pomocy zaleca najpierw zadbanie o bezpieczeństwo i unikanie przemieszczania poszkodowanego, o ile nie jest to konieczne. Przy poważnym urazie należy wezwać pomoc 112 i wykonywać polecenia dyspozytora. Animator nie powinien rutynowo sadzać dziecka, które po upadku nie może wstać, ani stawiać własnej diagnozy.","source_url":"https://www.gov.pl/web/poradnikbezpieczenstwa/pierwsza-pomoc","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='swiety-mikolaj' AND lesson_no=17 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Nie mieszaj produktów chlorowych (np. niektórych wybielaczy) z odkamieniaczami zawierającymi kwasy — może to uwalniać niebezpieczne gazy. Nie ma bezpiecznej «małej ilości» do wypróbowania w domu. Stosuj oryginalne opakowania i etykiety; w razie incydentu oddal się od miejsca narażenia i wezwij odpowiednią pomoc.","source_url":"","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='obowiazki-domowe' AND lesson_no=16 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
UPDATE public.ta_lessons SET material=jsonb_set(material,'{sections}',coalesce(material->'sections','[]'::jsonb)||'[{"heading":"Doprecyzowanie po kontroli źródłowej","text":"Średnia masa 4800/4 = 1200 kg nie służy jako wiarygodna masa najcięższej palety. Dla doboru urządzenia trzeba znać masy jednostkowe, środek ciężkości, sposób zawieszenia, udźwig przy danym promieniu i warunki podłoża; wynik 1200 kg jest jedynie średnią arytmetyczną.","source_url":"","verified_at":"2026-11-17"}]'::jsonb,true)||jsonb_build_object('fact_check_revision','2026-11-17-source-audit-v1'),updated_at=now() WHERE course_slug='brygadzista' AND lesson_no=12 AND material->>'redteam_audit_revision'='2026-11-17-adversarial-v3' AND material->>'fact_check_revision' IS DISTINCT FROM '2026-11-17-source-audit-v1';
COMMIT;
SELECT count(*) FILTER(WHERE material->>'redteam_audit_revision'='2026-11-17-adversarial-v3') reviewed,count(*) FILTER(WHERE material->>'fact_check_revision'='2026-11-17-source-audit-v1') fact_checked,count(*) FILTER(WHERE material->>'editorial_status'='needs_expert_review') pending,count(*) FILTER(WHERE material->'redteam_quiz'->>'human_approved'='true') false_approvals FROM public.ta_lessons WHERE material->>'editorial_status'='needs_expert_review';